        for (let attempt = 0; attempt < 50; attempt += 1) { const p = randomPoint(rng, 78); if (p.x < 205 && Math.abs(p.y - H / 2) < 95) continue; if (state.terrain.every((other) => dist(p, other) > radius + other.r * .45)) { point = p; break; } }
        point ||= { x: 300 + rng() * 520, y: 130 + rng() * 430 };
